package net.officefloor.hq.app.setting;

import java.time.LocalDate;
import java.util.List;

/** A validated settings form: the settings it sets, in the order they are recorded — the clerk limit, the floor, the
 *  terms, the late percent, the policy date, the period numbering from, the terms of grades A, B and C, the cap, the proof threshold. */
public record SettingsInput(List<Change> changes) {

    /** A setting the form sets: its key (as the audit names it), its value as the screen shows it (null: blank —
     *  no clerk limit, no cap, a grade on the sheet's terms, the policy date on the sheet's today, the period
     *  numbering off), and whether it is dated, and the from-date given (null: none given — a dated setting is then
     *  recorded from the sheet's today). */
    public record Change(String key, String value, boolean dated, LocalDate from) {
    }

    public boolean sets(String key) {
        return changes.stream().anyMatch(c -> c.key().equals(key));
    }
}
package net.officefloor.hq.app.setting;

/** The settings form as submitted: the clerk limit (blank: no limit), the floor (blank: 1.00) and the terms in
 *  days (blank: 14) and the late percent
 *  (blank: 0.00) and the policy date (YYYY-MM-DD; blank: the sheet's today) and the period numbering from (YYYY-MM-DD; blank: off) and the terms of grades A, B and C in days (blank: the sheet's terms) and the cap (blank: none) and the proof threshold (blank: none); a key left out (null) is not changed.
 *  Each setting that carries a figure has its from-date (YYYY-MM-DD; blank or left out: the sheet's today): it is
 *  recorded from that date on. */
public record SettingsRequest(String clerkLimit, String floor, String terms, String latePct, String policyDate, String periodNumberingFrom,
        String termsA, String termsB, String termsC, String cap, String proofThreshold,
        String clerkLimitFrom, String floorFrom, String termsFrom, String latePctFrom,
        String termsAFrom, String termsBFrom, String termsCFrom, String capFrom, String proofThresholdFrom) {
}
package net.officefloor.hq.app.setting;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetSetting;

/** The sheet's settings as the screen shows them, each in force on the sheet's today: the clerk limit with two decimals (null: no limit) and the
 *  floor with two decimals, and the terms in days, and the late percent with two decimals, and the policy date (YYYY-MM-DD; "" when
 *  blank: the sheet's today), and the period numbering from (YYYY-MM-DD; "" when off), and the own terms in days of grades A, B and C
 *  ("" when the grade uses the sheet's terms), and the cap with two decimals ("" when there is none), and the proof threshold with two decimals ("" when there is none); and the values recorded
 *  for each dated setting, by key (floor, late-pct, terms, terms-A/B/C, clerk-limit, cap), by from-date. */
public record SettingsResponse(String clerkLimit, String floor, String terms, String latePct, String policyDate,
        String periodNumberingFrom, String termsA, String termsB, String termsC, String cap, String proofThreshold,
        Map<String, List<Dated>> dated) {

    /** A value recorded from a date on (null from: the beginning of time; null value: blank). */
    public record Dated(String from, String value) {
    }

    public static SettingsResponse from(Sheet sheet) {
        Map<String, List<Dated>> dated = new LinkedHashMap<>();
        for (SheetSetting s : sheet.getSettings()) {
            dated.computeIfAbsent(s.getKey(), k -> new ArrayList<>())
                    .add(new Dated(s.getFromDate() == null ? null : s.getFromDate().toString(), s.getValue()));
        }
        return new SettingsResponse(sheet.getClerkLimit() == null ? null : sheet.getClerkLimit().toPlainString(),
                sheet.floorOn(sheet.getToday()).setScale(2).toPlainString(), String.valueOf(sheet.termsOn(sheet.getToday())),
                sheet.latePctOn(sheet.getToday()).setScale(2).toPlainString(),
                sheet.getPolicyDate() == null ? "" : sheet.getPolicyDate().toString(),
                sheet.getPeriodNumberingFrom() == null ? "" : sheet.getPeriodNumberingFrom().toString(),
                gradeTerms(sheet, "A"), gradeTerms(sheet, "B"), gradeTerms(sheet, "C"),
                sheet.getCap() == null ? "" : sheet.getCap().toPlainString(),
                sheet.proofThresholdOn(sheet.getToday()) == null ? "" : sheet.proofThresholdOn(sheet.getToday()).toPlainString(),
                dated);
    }

    /** The grade's own terms in days in force on the sheet's today; "" when it uses the sheet's terms. */
    public static String gradeTerms(Sheet sheet, String grade) {
        Integer terms = sheet.gradeTermsOn(grade, sheet.getToday());
        return terms == null ? "" : String.valueOf(terms);
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the settings form from the body; refuses a clerk limit or floor that is negative or has more than two
 *  decimals, and terms that are not a whole number of days, and a late percent that is negative or has more than two decimals, and a policy date or period numbering from that is not a calendar date
 *  (YYYY-MM-DD). A blank clerk limit means no limit; a blank floor is
 *  1.00; blank terms are 14; a blank late percent is 0.00; a blank policy date is the sheet's today; a blank period numbering from is off; a blank cap is none (else an amount like the floor); a blank proof threshold is none (else an amount like the floor). A grade's terms must be a whole number of days, or blank (the grade uses the sheet's terms). A key left out is not changed.
 *  A from-date must be a calendar date (YYYY-MM-DD), or blank (the sheet's today). */
public class ValidateSettings {

    private static final Pattern DAYS = Pattern.compile("\\d{1,5}");

    private static final Pattern AMOUNT = Pattern.compile("\\d+(\\.\\d{1,2})?");

    public void validate(@RequestBody SettingsRequest request, Out<SettingsInput> body) throws InvalidSettingsException {
        List<SettingsInput.Change> changes = new ArrayList<>();
        if (request != null) {
            amount(changes, Sheet.CLERK_LIMIT, request.clerkLimit(), null, request.clerkLimitFrom(),
                    "The clerk limit must be an amount, 0.00 or more, with up to two decimals, or blank.");
            amount(changes, Sheet.FLOOR, request.floor(), Sheet.DEFAULT_FLOOR, request.floorFrom(),
                    "The floor must be an amount, 0.00 or more, with up to two decimals, or blank.");
            days(changes, Sheet.TERMS, request.terms(), Sheet.DEFAULT_TERMS, request.termsFrom(),
                    "The terms must be a whole number of days, 0 or more, or blank.");
            amount(changes, Sheet.LATE_PCT, request.latePct(), Sheet.DEFAULT_LATE_PCT, request.latePctFrom(),
                    "The late percent must be a percent, 0.00 or more, with up to two decimals, or blank.");
            date(changes, "policy-date", request.policyDate(), "The policy date must be a date (YYYY-MM-DD), or blank.");
            date(changes, "period-numbering-from", request.periodNumberingFrom(),
                    "The period numbering from must be a date (YYYY-MM-DD), or blank.");
            days(changes, Sheet.TERMS + "-A", request.termsA(), null, request.termsAFrom(),
                    "The terms of grade A must be a whole number of days, 0 or more, or blank.");
            days(changes, Sheet.TERMS + "-B", request.termsB(), null, request.termsBFrom(),
                    "The terms of grade B must be a whole number of days, 0 or more, or blank.");
            days(changes, Sheet.TERMS + "-C", request.termsC(), null, request.termsCFrom(),
                    "The terms of grade C must be a whole number of days, 0 or more, or blank.");
            amount(changes, Sheet.CAP, request.cap(), null, request.capFrom(),
                    "The cap must be an amount, 0.00 or more, with up to two decimals, or blank.");
            amount(changes, Sheet.PROOF_THRESHOLD, request.proofThreshold(), null, request.proofThresholdFrom(),
                    "The proof threshold must be an amount, 0.00 or more, with up to two decimals, or blank.");
        }
        body.set(new SettingsInput(changes));
    }

    /** Adds an amount setting when the form sets it: blank is the given default (null: none). */
    private static void amount(List<SettingsInput.Change> changes, String key, String value, BigDecimal blank,
            String from, String message) throws InvalidSettingsException {
        if (value == null) {
            return;
        }
        BigDecimal amount = blank;
        if (!value.trim().isEmpty()) {
            if (!AMOUNT.matcher(value.trim()).matches()) {
                throw new InvalidSettingsException(message);
            }
            amount = new BigDecimal(value.trim());
        }
        changes.add(new SettingsInput.Change(key, amount == null ? null : amount.setScale(2).toPlainString(), true,
                from(key, from)));
    }

    /** Adds a whole-days setting when the form sets it: blank is the given default (null: none). */
    private static void days(List<SettingsInput.Change> changes, String key, String value, Integer blank,
            String from, String message) throws InvalidSettingsException {
        if (value == null) {
            return;
        }
        Integer days = blank;
        if (!value.trim().isEmpty()) {
            if (!DAYS.matcher(value.trim()).matches()) {
                throw new InvalidSettingsException(message);
            }
            days = Integer.parseInt(value.trim());
        }
        changes.add(new SettingsInput.Change(key, days == null ? null : String.valueOf(days), true, from(key, from)));
    }

    /** Adds an undated date setting when the form sets it: blank is null. */
    private static void date(List<SettingsInput.Change> changes, String key, String value, String message)
            throws InvalidSettingsException {
        if (value == null) {
            return;
        }
        LocalDate date = null;
        if (!value.trim().isEmpty()) {
            try {
                date = LocalDate.parse(value.trim());
            } catch (DateTimeParseException e) {
                throw new InvalidSettingsException(message);
            }
        }
        changes.add(new SettingsInput.Change(key, date == null ? null : date.toString(), false, null));
    }

    /** A setting's from-date: null when blank or left out (the sheet's today). */
    private static LocalDate from(String key, String from) throws InvalidSettingsException {
        if (from == null || from.trim().isEmpty()) {
            return null;
        }
        try {
            return LocalDate.parse(from.trim());
        } catch (DateTimeParseException e) {
            throw new InvalidSettingsException("The from-date of the " + key + " must be a date (YYYY-MM-DD), or blank.");
        }
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.ManyToOne;
import jakarta.persistence.Table;
import java.time.LocalDate;

/** A dated setting of a sheet: the value a setting key (floor, late-pct, terms, terms-A/B/C, clerk-limit, cap) has
 *  from its from-date on (null: from the beginning of time); the value as the screen shows it, null for none. */
@Entity
@Table(name = "sheet_setting")
public class SheetSetting {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(optional = false)
    @JoinColumn(name = "sheet_id", nullable = false)
    private Sheet sheet;

    @Column(name = "setting_key", nullable = false)
    private String key;

    @Column(name = "from_date")
    private LocalDate fromDate;

    @Column(name = "setting_value")
    private String value;

    protected SheetSetting() {
    }

    SheetSetting(Sheet sheet, String key, LocalDate fromDate, String value) {
        this.sheet = sheet;
        this.key = key;
        this.fromDate = fromDate;
        this.value = value;
    }

    public String getKey() {
        return key;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public String getValue() {
        return value;
    }

    void setValue(String value) {
        this.value = value;
    }
}
-- A sheet's dated settings: the value of a setting that carries a figure (floor, late-pct, terms, terms-A/B/C,
-- clerk-limit, cap) from a from-date on. The value in force on a date is the one with the latest from-date on or
-- before it; a row with no from-date applies from the beginning of time; before every from-date the sheet's
-- starting value applies (floor 1.00, late-pct 0.00, terms 14; none for the others). The value is as the screen
-- shows it; null (blank) for none. The sheet's old setting columns are no longer read: their values are carried
-- over here, from the beginning of time.
CREATE TABLE sheet_setting (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    setting_key VARCHAR(40) NOT NULL,
    from_date DATE,
    setting_value VARCHAR(40)
);
CREATE INDEX sheet_setting_sheet ON sheet_setting (sheet_id, setting_key);
INSERT INTO sheet_setting (sheet_id, setting_key, setting_value)
    SELECT id, 'floor', CAST(floor AS VARCHAR) FROM sheet WHERE floor <> 1.00;
INSERT INTO sheet_setting (sheet_id, setting_key, setting_value)
    SELECT id, 'late-pct', CAST(late_pct AS VARCHAR) FROM sheet WHERE late_pct <> 0.00;
INSERT INTO sheet_setting (sheet_id, setting_key, setting_value)
    SELECT id, 'terms', CAST(terms AS VARCHAR) FROM sheet WHERE terms <> 14;
INSERT INTO sheet_setting (sheet_id, setting_key, setting_value)
    SELECT id, 'terms-A', CAST(terms_a AS VARCHAR) FROM sheet WHERE terms_a IS NOT NULL;
INSERT INTO sheet_setting (sheet_id, setting_key, setting_value)
    SELECT id, 'terms-B', CAST(terms_b AS VARCHAR) FROM sheet WHERE terms_b IS NOT NULL;
INSERT INTO sheet_setting (sheet_id, setting_key, setting_value)
    SELECT id, 'terms-C', CAST(terms_c AS VARCHAR) FROM sheet WHERE terms_c IS NOT NULL;
INSERT INTO sheet_setting (sheet_id, setting_key, setting_value)
    SELECT id, 'clerk-limit', CAST(clerk_limit AS VARCHAR) FROM sheet WHERE clerk_limit IS NOT NULL;
INSERT INTO sheet_setting (sheet_id, setting_key, setting_value)
    SELECT id, 'cap', CAST(cap AS VARCHAR) FROM sheet WHERE cap IS NOT NULL;

